'use strict';class LocationSampler{constructor(opts={}){this._opts=Object.assign({geofenceId:null,visitId:null,ring:[],bbox:null,syncQueue:null,geofenceManager:null,minAccuracyM:30,maxAccuracyM:150,baseIntervalSec:30,maxIntervalSec:120,stationaryThresholdM:3,onInZone:null,onOutZone:null,onSampleCollected:null,onError:null,},opts);this._running=!1;this._watchId=null;this._intervalId=null;this._lastLat=null;this._lastLng=null;this._lastTs=null;this._lastInZone=null;this._stationary=!1;this._sampleCount=0;this._currentInterval=this._opts.baseIntervalSec;this._onVisibilityChange=()=>this._handleVisibilityChange()}
start(){if(this._running)return;if(!navigator.geolocation){this._error('Geolocation API not available on this device.');return}
if(!this._opts.visitId||!this._opts.geofenceId){this._error('visitId and geofenceId are required to start sampling.');return}
if(!this._opts.syncQueue){this._error('syncQueue is required.');return}
this._running=!0;this._startWatch();document.addEventListener('visibilitychange',this._onVisibilityChange);console.debug('[LocationSampler] Started. Visit:',this._opts.visitId,'Geofence:',this._opts.geofenceId)}
stop(){if(!this._running)return;this._running=!1;this._stopWatch();document.removeEventListener('visibilitychange',this._onVisibilityChange);if(this._opts.syncQueue){this._opts.syncQueue.flush()}
console.debug('[LocationSampler] Stopped. Total samples:',this._sampleCount)}
get isRunning(){return this._running}
get sampleCount(){return this._sampleCount}
get lastInZone(){return this._lastInZone}
_startWatch(){const geoOpts={enableHighAccuracy:!0,maximumAge:10000,timeout:20000,};this._watchId=navigator.geolocation.watchPosition((pos)=>this._onPosition(pos),(err)=>this._onGeoError(err),geoOpts);this._scheduleBackupPoll()}
_stopWatch(){if(this._watchId!==null){navigator.geolocation.clearWatch(this._watchId);this._watchId=null}
if(this._intervalId!==null){clearTimeout(this._intervalId);this._intervalId=null}}
_scheduleBackupPoll(){if(!this._running)return;this._intervalId=setTimeout(()=>{navigator.geolocation.getCurrentPosition((pos)=>this._onPosition(pos),(err)=>this._onGeoError(err),{enableHighAccuracy:!0,maximumAge:5000,timeout:10000});this._scheduleBackupPoll()},this._currentInterval*1000)}
_onPosition(pos){if(!this._running)return;const lat=pos.coords.latitude;const lng=pos.coords.longitude;const acc=pos.coords.accuracy;const ts=pos.timestamp;if(acc>this._opts.maxAccuracyM){console.debug('[LocationSampler] Fix too inaccurate, skipping.',acc,'m');return}
if(this._lastTs&&(ts-this._lastTs)<(this._opts.baseIntervalSec*1000*0.8)){return}
const inZone=this._checkInZone(lat,lng);const moved=this._hasMoved(lat,lng);this._updateAdaptiveInterval(moved);const sample={lat,lng,accuracy_m:acc,speed_mps:pos.coords.speed!==null?pos.coords.speed:null,heading:pos.coords.heading!==null?pos.coords.heading:null,altitude_m:pos.coords.altitude!==null?pos.coords.altitude:null,battery_pct:null,source:'gps',timestamp:ts,in_zone:inZone,};this._getBatteryPct().then(pct=>{if(pct!==null)sample.battery_pct=pct});this._opts.syncQueue.enqueue(sample);this._sampleCount++;if(this._opts.geofenceManager){this._opts.geofenceManager.updateCrewPosition(lat,lng,inZone)}
if(inZone!==this._lastInZone){this._lastInZone=inZone;if(inZone){if(typeof this._opts.onInZone==='function')this._opts.onInZone();}else{if(typeof this._opts.onOutZone==='function')this._opts.onOutZone();}}
if(typeof this._opts.onSampleCollected==='function'){this._opts.onSampleCollected(sample)}
this._lastLat=lat;this._lastLng=lng;this._lastTs=ts}
_onGeoError(err){const msg=['','GPS permission denied.','GPS signal unavailable.','GPS timeout.'][err.code]||'GPS error.';if(err.code===1){this.stop()}
this._error(msg+' (code '+err.code+')')}
_checkInZone(lat,lng){const ring=this._opts.ring;if(!ring||ring.length<3)return!1;const bb=this._opts.bbox;if(bb){if(lat<bb.lat_min||lat>bb.lat_max)return!1;if(lng<bb.lng_min||lng>bb.lng_max)return!1}
return this._pointInPolygon(lat,lng,ring)}
_pointInPolygon(lat,lng,polygon){let inside=!1;const n=polygon.length;let j=n-1;for(let i=0;i<n;i++){const xi=polygon[i][0],yi=polygon[i][1];const xj=polygon[j][0],yj=polygon[j][1];const intersect=((yi>lng)!==(yj>lng))&&(lat<(xj-xi)*(lng-yi)/(yj-yi)+xi);if(intersect)inside=!inside;j=i}
return inside}
_hasMoved(lat,lng){if(this._lastLat===null)return!0;const R=6371000;const dLat=(lat-this._lastLat)*Math.PI/180;const dLng=(lng-this._lastLng)*Math.PI/180;const a=Math.sin(dLat/2)**2+Math.cos(this._lastLat*Math.PI/180)*Math.cos(lat*Math.PI/180)*Math.sin(dLng/2)**2;const dist=R*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));return dist>=this._opts.stationaryThresholdM}
_updateAdaptiveInterval(moved){if(moved){this._currentInterval=this._opts.baseIntervalSec;this._stationary=!1}else{this._stationary=!0;this._currentInterval=Math.min(this._currentInterval*1.5,this._opts.maxIntervalSec)}}
_getBatteryPct(){if(!navigator.getBattery)return Promise.resolve(null);return navigator.getBattery().then(bat=>Math.round(bat.level*100)).catch(()=>null)}
_handleVisibilityChange(){if(!this._running)return;if(document.hidden){this._backgroundStartTs=Date.now();console.debug('[LocationSampler] App went to background at',this._backgroundStartTs)}else{if(this._backgroundStartTs){const gapSec=Math.round((Date.now()-this._backgroundStartTs)/1000);console.debug('[LocationSampler] Returned from background after',gapSec,'s gap');this._backgroundStartTs=null;navigator.geolocation.getCurrentPosition((pos)=>this._onPosition(pos),()=>{},{enableHighAccuracy:!0,maximumAge:0,timeout:10000})}}}
_error(msg){console.warn('[LocationSampler]',msg);if(typeof this._opts.onError==='function')this._opts.onError(msg);}}
if(typeof module!=='undefined'&&module.exports){module.exports={LocationSampler}}else{window.LocationSampler=LocationSampler}